def create_scholar_link_file(search_query: str, file_path: Path):
    encoded_query = urllib.parse.quote_plus(search_query)
    scholar_url = f"https://scholar.google.com/scholar?q={encoded_query}"
    html_content = f'''<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <meta http-equiv="refresh" content="0; url={scholar_url}">
    <title>Google Scholar Search: {search_query}</title>
</head>
<body>
    <p>Redirecting to Google Scholar...</p>
    <p>If you are not redirected automatically, <a href="{scholar_url}">click here</a>.</p>
</body>
</html>'''

    with open(file_path, "w", encoding="utf-8") as f:
        f.write(html_content)


def create_file_structure(gisd_file_path: Path, output_path: Path):
    df = pd.read_excel(gisd_file_path)
    groupings = df.groupby(["Reference", "Species"])
    with Progress() as p:
        task: TaskID = p.add_task(
            "Generating evaluation set... ", total=groupings.size().sum()
        )
        for name, group in groupings:
            reference, species = name

            dir_name: str = abs(hash(reference)).to_bytes(8, "big").hex()
            dir_path: Path = output_path / dir_name
            dir_path.mkdir(exist_ok=True, parents=True)

            create_scholar_link_file(reference, dir_path / "reference.html")

            group.to_csv(
                dir_path / f"gold_impacts_{slugify(species, separator='_')}.csv", index=False
            )
            p.update(task, advance=len(group))


def download(
    output_path: Path,
    url: str = GISD_URL,
) -> Path:
    file_path: Path = output_path / "gisd.xlsx"

    if file_path.exists():
        return file_path

    file_path.parent.mkdir(exist_ok=True, parents=True)
    response: Response = get(url)

    with Progress() as p, open(file_path, "wb") as f:
        task = p.add_task("Downloading...")

        total_size = int(response.headers.get("content-length", 0))
        p.update(task, total=total_size)

        downloaded: int = 0
        for chunk in response.iter_content(chunk_size=8192):
            if chunk:
                downloaded += f.write(chunk)
                p.update(
                    task,
                    completed=downloaded,
                    description=f"Downloading {output_path}",
                )
    return file_path


def main(
    output_path: Annotated[
        Path,
        typer.Option(
            "-o", "--output-path", help="Path to save the evaluation data to."
        ),
    ],
) -> None:
    gisd_file_path = download(output_path)
    create_file_structure(gisd_file_path, output_path)


if __name__ == "__main__":
    typer.run(main)
